Object.assign(GSB,{
"g|eo|C2|Modus Imperatif (-u)":[["Nu, rigardu tion!","","Nah, lihatlah itu!","rigardu","lihatlah"],["Ho, venu ĉi tien!","","Oh, kemarilah!","venu","kemarilah"],["Nu, atentu la ŝtupon!","","Nah, hati-hati dengan anak tangga itu!","atentu","hati-hati"],["Nu, lasu min en paco!","","Nah, tinggalkan saya dalam damai!","lasu","tinggalkan"],["Nun fermu la pordon kaj sidiĝu.","","Sekarang tutup pintu dan duduklah.","fermu","tutup"],["Unue skribu vian nomon sur la paĝo.","","Pertama, tulislah namamu di halaman itu.","skribu","tulislah"],["Antaŭ ol foriri, prenu vian ĉapelon.","","Sebelum pergi, ambillah topimu.","prenu","ambillah"],["Nun aŭskultu bone, ĉar mi diros tion nur unufoje.","","Sekarang dengarkan baik-baik, karena saya akan mengatakannya hanya sekali.","aŭskultu","dengarkan"],["Kiam vi alvenos, telefonu al mi tuj.","","Ketika kamu tiba, telepon saya segera.","telefonu","telepon"],["Se vi havas demandon, levu la manon kaj atendu.","","Jika kamu punya pertanyaan, angkat tangan dan tunggu.","levu","angkat"],["Bonvolu resti kviete, kaj nun parolu malrapide.","","Tolong tetap tenang, dan sekarang bicaralah pelan-pelan.","parolu","bicaralah"],["Post la lasta kruciĝo turnu dekstren kaj iru rekte ĝis la ponto.","","Setelah persimpangan terakhir, belok kananlah dan jalan lurus sampai jembatan.","turnu","belok"]],
"g|eo|C2|Tekad dan Ajakan (Orang I)":[["Nu, mi pensu pri tio.","","Biar saya pikirkan hal itu.","mi pensu","Biar saya"],["Do, mi kuiru la vespermanĝon hodiaŭ.","","Jadi, biar saya yang memasak makan malam hari ini.","mi kuiru","biar saya"],["Ne maltrankviliĝu, mi pagu la fakturon.","","Jangan khawatir, biar saya yang membayar tagihannya.","mi pagu","biar saya"],["Ho, mi rakontu al vi, kio okazis.","","Oh, biar saya ceritakan kepadamu apa yang terjadi.","mi rakontu","biar saya"],["Vi estas laca; mi veturu la aŭton.","","Kamu lelah; biar saya yang menyetir mobil.","mi veturu","biar saya"],["Atendu, mi helpu vin porti la pakaĵojn.","","Tunggu, biar saya membantumu membawa bagasi.","mi helpu","biar saya"],["Ne vekiĝu, mi portu la bebon al la lito.","","Jangan bangun, biar saya yang membawa bayi itu ke tempat tidur.","mi portu","biar saya"],["Sidiĝu kaj ripozu, mi lavu la telerojn.","","Duduklah dan istirahat, biar saya yang mencuci piringnya.","mi lavu","biar saya"],["Tiu ĉi demando estas malfacila, sed mi provu respondi.","","Pertanyaan ini sulit, tetapi biar saya mencoba menjawab.","mi provu","biar saya"],["Vi ne scias la vojon; mi gvidu vin al la stacidomo.","","Kamu tidak tahu jalannya; biar saya menuntunmu ke stasiun.","mi gvidu","biar saya"],["Se nenio alia helpas, mi telefonu al la kuracisto.","","Jika tidak ada yang lain membantu, biar saya menelepon dokter.","mi telefonu","biar saya"],["Baldaŭ mallumiĝos, do mi iru kaj rigardu, ĉu la pordo estas fermita.","","Sebentar lagi gelap, jadi biar saya pergi dan melihat apakah pintu itu tertutup.","mi iru","biar saya"]],
"g|eo|C2|Ajakan dengan ni + -u":[["Bone, ni iru hejmen.","","Baiklah, mari kita pulang.","ni iru","mari kita"],["Nu, ni komencu la laboron.","","Nah, mari kita mulai pekerjaan itu.","ni komencu","mari kita"],["Hodiaŭ ni manĝu en restoracio.","","Hari ini mari kita makan di restoran.","ni manĝu","mari kita"],["Venu, ni ludu ŝakon.","","Ayo, mari kita main catur.","ni ludu","mari kita"],["Post la lernejo ni promenu laŭ la rivero.","","Sepulang sekolah mari kita berjalan menyusuri sungai.","ni promenu","mari kita"],["Ĉar pluvas, ni restu hejme kaj spektu filmon.","","Karena hujan, mari kita tinggal di rumah dan menonton film.","ni restu","mari kita"],["Antaŭ ol ni decidos, ni aŭskultu ĉiujn opiniojn.","","Sebelum memutuskan, mari kita dengarkan semua pendapat.","ni aŭskultu","mari kita"],["Jam estas malfrue; ni ne perdu pli da tempo.","","Sudah larut; mari kita jangan buang waktu lagi.","ni ne perdu","mari kita"],["Kaj ni ne forgesu, ke morgaŭ estas la ekzameno.","","Dan jangan sampai kita lupa bahwa besok ada ujian.","ni ne forgesu","jangan sampai kita"],["Por la naskiĝtago de nia patrino ni aĉetu belan donacon.","","Untuk ulang tahun ibu kita, mari kita membeli hadiah yang indah.","ni aĉetu","mari kita"],["Se ni volas atingi la celon, ni laboru pli diligente.","","Jika kita ingin mencapai tujuan, mari kita bekerja lebih rajin.","ni laboru","mari kita"],["Nun ni ĉiuj kune kantu la himnon.","","Sekarang mari kita semua bernyanyi bersama lagu kebangsaan.","ni ĉiuj kune kantu","mari kita"]],
"g|eo|C2|Perintah dan Larangan (Orang II/III)":[["Nun estu trankvila, mia kara.","","Sekarang tenanglah, sayangku.","estu","tenanglah"],["Rapidu, kaj ne perdu tempon!","","Cepatlah, dan jangan buang waktu!","Rapidu","Cepatlah"],["Nu, li venu tuj, se li volas helpi.","","Nah, biarlah dia datang segera kalau dia mau membantu.","li venu","biarlah dia"],["Bone, ŝi atendu ekstere.","","Baiklah, biarlah dia menunggu di luar.","ŝi atendu","biarlah dia"],["Nun silentu kaj aŭskultu la muzikon.","","Sekarang diamlah dan dengarkan musik itu.","silentu","diamlah"],["Memoru: ili ne tuŝu la bildojn en la muzeo.","","Ingat: jangan biarkan mereka menyentuh lukisan di museum.","ili ne tuŝu","jangan biarkan mereka"],["Atendu, la knaboj eniru unuope.","","Tunggu, biarlah anak-anak itu masuk satu per satu.","eniru","biarlah"],["Nu, ili mem decidu, kion ili faros.","","Nah, biarlah mereka sendiri memutuskan apa yang akan mereka lakukan.","decidu","biarlah mereka"],["Kaj ĉiu respondu laŭ sia propra opinio.","","Dan biarlah setiap orang menjawab menurut pendapatnya sendiri.","respondu","biarlah"],["Kiu volas helpi, tiu restu post la kunveno.","","Siapa yang mau membantu, biarlah tetap tinggal setelah rapat.","restu","biarlah"],["La instruisto parolu unue, kaj poste la studentoj demandu.","","Biarlah guru berbicara dahulu, lalu para siswa bertanya.","parolu","Biarlah"],["Se la gastoj alvenos, ili sidiĝu kaj ĝuu la manĝon.","","Jika para tamu tiba, biarlah mereka duduk dan menikmati makanan.","sidiĝu","biarlah mereka"]],
"g|eo|C2|Larangan dengan ne + -u":[["Nun ne parolu, la bebo dormas.","","Sekarang jangan bicara, bayinya sedang tidur.","ne parolu","jangan bicara"],["Bonvolu, ne fermu la fenestron.","","Tolong, jangan tutup jendelanya.","ne fermu","jangan tutup"],["Kaj ne forgesu viajn ŝlosilojn!","","Dan jangan lupa kunci-kuncimu!","ne forgesu","jangan lupa"],["Infanoj, ne tuŝu la varman fornon!","","Anak-anak, jangan sentuh kompor yang panas!","ne tuŝu","jangan sentuh"],["Mia kara, ne ploru, ĉio estos en ordo.","","Sayangku, jangan menangis, semuanya akan baik-baik saja.","ne ploru","jangan menangis"],["Dum la ekzameno ne uzu vian telefonon.","","Selama ujian jangan gunakan ponselmu.","ne uzu","jangan gunakan"],["Pro la pluvo ne iru sen ombrelo.","","Karena hujan, jangan pergi tanpa payung.","ne iru","jangan pergi"],["Se vi vidas lupon, ne kuru, sed restu trankvila.","","Jika kamu melihat serigala, jangan berlari, tetapi tetaplah tenang.","ne kuru","jangan berlari"],["Kiam vi veturas, ne dormu eĉ unu sekundon.","","Saat mengemudi, jangan tidur sedetik pun.","ne dormu","jangan tidur"],["En la biblioteko ne faru bruon kaj parolu mallaŭte.","","Di perpustakaan jangan membuat keributan dan bicaralah pelan.","ne faru","jangan membuat"],["Eĉ se li koleras, ne respondu al li en la sama tono.","","Meskipun dia marah, jangan jawab dia dengan nada yang sama.","ne respondu","jangan jawab"],["Pro la glacio sur la vojo ne rapidu, ĉar la aŭto povas gliti.","","Karena es di jalan jangan terburu-buru, sebab mobil bisa tergelincir.","ne rapidu","jangan terburu-buru"]],
"g|eo|C2|Imperatif untuk Permohonan, Harapan, Saran":[["Helpu min, mi petas.","","Bantu saya, saya mohon.","mi petas","saya mohon"],["Atendu momenton, mi petas.","","Tunggulah sebentar, saya mohon.","mi petas","saya mohon"],["Donu al mi la libron, mi petas.","","Berikan buku itu kepada saya, saya mohon.","mi petas","saya mohon"],["Respondu al mia letero, mi petas.","","Balaslah surat saya, saya mohon.","mi petas","saya mohon"],["Ne foriru ankoraŭ, mi petas.","","Jangan pergi dulu, saya mohon.","mi petas","saya mohon"],["Sidiĝu kaj aŭskultu min, mi petas.","","Duduklah dan dengarkan saya, saya mohon.","mi petas","saya mohon"],["Pardonu min pro la malfruo, mi petas.","","Maafkan saya atas keterlambatan itu, saya mohon.","mi petas","saya mohon"],["Pardonu al li, mi petas, ĉar li ne volis vundi vin.","","Maafkanlah dia, saya mohon, karena dia tidak bermaksud menyakitimu.","mi petas","saya mohon"],["Gardu la sekreton, mi petas, ĉar ĝi estas tre grava por mi.","","Jagalah rahasia itu, saya mohon, karena sangat penting bagi saya.","mi petas","saya mohon"],["Zorgu pri la infano, mi petas, dum mi iras al la vendejo.","","Jagalah anak itu, saya mohon, selama saya pergi ke toko.","mi petas","saya mohon"],["Donu al ni iom pli da tempo, mi petas, ĉar ni ankoraŭ ne finis.","","Beri kami sedikit waktu lagi, saya mohon, karena kami belum selesai.","mi petas","saya mohon"]],
"g|eo|C2|Imperatif untuk Harapan":[["Ho, Dio vin benu!","","Oh, semoga Tuhan memberkatimu!","benu","Semoga"],["Kaj vivu la reĝino!","","Dan hiduplah sang ratu!","vivu","hiduplah"],["Jen, longe vivu nia amikeco!","","Nah, semoga persahabatan kita berumur panjang!","vivu","semoga"],["Ĉielo gardu vin kaj vian familion.","","Semoga langit menjagamu dan keluargamu.","gardu","Semoga"],["Kaj ĉio iru bone kun vi en la nova urbo!","","Semoga segalanya berjalan baik bagimu di kota baru!","iru","Semoga"],["Kaj la paco regu en la tuta mondo!","","Semoga perdamaian berkuasa di seluruh dunia!","regu","Semoga"],["Kaj la feliĉo akompanu vin ĉe la ekzameno morgaŭ!","","Semoga keberuntungan menyertaimu pada ujian besok!","akompanu","Semoga"],["Ho, la vetero estu bona dum nia ekskurso!","","Oh, semoga cuaca baik selama tamasya kami!","estu","semoga"],["Ho, ripozu vi bone en la nova hejmo!","","Oh, semoga kamu beristirahat dengan baik di rumah baru!","ripozu","semoga"],["Ho, venu la tago, kiam ni ĉiuj povos vivi sen milito.","","Oh, semoga datang hari ketika kita semua bisa hidup tanpa perang.","venu","semoga"],["Nia lando prosperu kaj ĝiaj loĝantoj ĝuu liberecon.","","Semoga negara kita makmur dan penduduknya menikmati kebebasan.","prosperu","Semoga"],["Kaj ĉiu tago de via vivo estu plena de ĝojo kaj sano.","","Semoga setiap hari hidupmu penuh sukacita dan kesehatan.","estu","Semoga"]],
"g|eo|C2|Imperatif untuk Saran dan Pertimbangan":[["Ĉu mi faru tion aŭ ne?","","Haruskah saya melakukan itu atau tidak?","faru","Haruskah"],["Ĉu mi telefonu al li nun?","","Haruskah saya menelepon dia sekarang?","telefonu","Haruskah"],["Ĉu ni iru al la kino aŭ restu hejme?","","Haruskah kita pergi ke bioskop atau tinggal di rumah?","iru","Haruskah"],["Kion mi aĉetu por la naskiĝtago de mia patrino?","","Apa yang sebaiknya saya beli untuk ulang tahun ibu saya?","aĉetu","sebaiknya"],["Kiam ni ekiru, por ke ni ne malfruiĝu?","","Kapan sebaiknya kita berangkat supaya tidak terlambat?","ekiru","sebaiknya"],["Kiun libron mi legu unue?","","Buku mana yang sebaiknya saya baca lebih dulu?","legu","sebaiknya"],["Ĉu mi diru la veron al li aŭ silentu?","","Haruskah saya mengatakan yang sebenarnya kepadanya atau diam?","diru","Haruskah"],["Ĉu ni atendu la aliajn aŭ komencu sen ili?","","Haruskah kita menunggu yang lain atau mulai tanpa mereka?","atendu","Haruskah"],["Ĉu mi eniru sen frapi aŭ atendu ekstere?","","Haruskah saya masuk tanpa mengetuk atau menunggu di luar?","eniru","Haruskah"],["Kiel mi respondu al tiel malĝentila letero?","","Bagaimana sebaiknya saya menjawab surat yang begitu tidak sopan?","respondu","sebaiknya"],["Ĉu ni voku la policon aŭ ĉu ni solvu la problemon mem?","","Haruskah kita memanggil polisi atau menyelesaikan masalah itu sendiri?","voku","Haruskah"],["Kien ni veturu dum la ferio, al la maro aŭ al la montoj?","","Ke mana sebaiknya kita pergi berlibur, ke laut atau ke gunung?","veturu","sebaiknya"]],
"g|eo|C2|Sebutan Kehormatan moŝto":[["Via moŝto, la kaleŝo jam atendas.","","Yang Mulia, kereta sudah menunggu.","moŝto","Yang Mulia"],["Lia moŝto la reĝo ankoraŭ dormas.","","Yang Mulia Raja masih tidur.","moŝto","Yang Mulia"],["Ĉu via moŝto deziras ankoraŭ iom da teo?","","Apakah Yang Mulia ingin sedikit teh lagi?","moŝto","Yang Mulia"],["Ŝia moŝto la reĝino vizitis la hospitalon hieraŭ.","","Yang Mulia Ratu mengunjungi rumah sakit kemarin.","moŝto","Yang Mulia"],["Ŝia imperiestra moŝto alvenos je la deka horo.","","Yang Mulia Kaisar akan tiba pukul sepuluh.","moŝto","Yang Mulia"],["Ni esperas, ke lia moŝto resaniĝos baldaŭ.","","Kami berharap Yang Mulia segera sembuh.","moŝto","Yang Mulia"],["Mi havas la honoron saluti vian reĝan moŝton.","","Saya mendapat kehormatan menyapa Yang Mulia Raja Anda.","moŝton","Yang Mulia"],["Antaŭ ol ŝia moŝto prenis la forkon, neniu ekmanĝis.","","Sebelum Yang Mulia mengambil garpunya, tak seorang pun mulai makan.","moŝto","Yang Mulia"],["Per la permeso de via moŝto, ni komencos la ceremonion.","","Dengan izin Yang Mulia, kami akan memulai upacara.","moŝto","Yang Mulia"],["La ambasadoro sendis leteron al lia moŝto la reĝo.","","Duta besar mengirim surat kepada Yang Mulia Raja.","moŝto","Yang Mulia"],["Sinjoro, ĉu mi rajtas demandi ion al via moŝto?","","Tuan, bolehkah saya bertanya sesuatu kepada Yang Mulia?","moŝto","Yang Mulia"],["Ŝia reĝa moŝto parolis al la popolo de sur la balkono.","","Yang Mulia Ratu berbicara kepada rakyat dari balkon.","moŝto","Yang Mulia"],["Mia patro iam salutis lian moŝton, kiam la reĝo vizitis nian urbon.","","Ayah saya pernah menyapa Yang Mulia ketika raja mengunjungi kota kami.","moŝton","Yang Mulia"],["La ĵurnalistoj atendis la eliron de ŝia moŝto la reĝino el la palaco.","","Para wartawan menunggu keluarnya Yang Mulia Ratu dari istana.","moŝto","Yang Mulia"],["La parlamento deziras al ŝia moŝto longan vivon kaj feliĉon.","","Parlemen mengharapkan Yang Mulia umur panjang dan kebahagiaan.","moŝto","Yang Mulia"]],
"g|eo|C2|Imperatif dalam Anak Kalimat (ke)":[["Mi petas, ke vi venu.","","Saya meminta agar kamu datang.","venu","agar"],["Ŝi ordonis, ke ni silentu.","","Dia memerintahkan agar kita diam.","silentu","agar"],["Mi volas, ke vi ne forgesu mian naskiĝtagon.","","Saya ingin agar kamu tidak melupakan ulang tahunku.","forgesu","agar"],["Mi deziras, ke vi estu feliĉa.","","Saya berharap agar kamu bahagia.","estu","agar"],["La instruisto postulas, ke ĉiuj alportu la lernolibron.","","Guru menuntut agar semua membawa buku pelajaran.","alportu","agar"],["Mia patrino insistas, ke mi manĝu pli multe.","","Ibu saya mendesak agar saya makan lebih banyak.","manĝu","agar"],["Ni proponas, ke la kunveno okazu lundon.","","Kami mengusulkan agar rapat diadakan hari Senin.","okazu","agar"],["La kuracisto konsilis, ke mi ripozu dum semajno.","","Dokter menyarankan agar saya beristirahat selama seminggu.","ripozu","agar"],["Ŝi atentigis nin, ke ni ne perdu la bileton.","","Dia mengingatkan kami agar jangan kehilangan karcis.","perdu","agar"],["Mi sugestas, ke ni prenu taksion, ĉar pluvas forte.","","Saya menyarankan agar kita naik taksi karena hujan deras.","prenu","agar"],["La estro ordonis, ke ni finu la laboron ĝis vendredo.","","Atasan memerintahkan agar kami menyelesaikan pekerjaan sampai Jumat.","finu","agar"],["La polico postulis, ke la ŝoforo elŝaltu la motoron.","","Polisi menuntut agar sopir mematikan mesin.","elŝaltu","agar"],["Estas grave, ke ĉiu ŝanĝo estu dokumentita zorge.","","Penting agar setiap perubahan didokumentasikan dengan cermat.","estu","agar"],["La reĝo decidis, ke la ĉefurbo ricevu novan placon antaŭ la festo.","","Raja memutuskan agar ibu kota menerima alun-alun baru sebelum pesta.","ricevu","agar"],["Ŝi petis, ke la najbaroj ne faru bruon post la deka vespere.","","Dia meminta agar para tetangga tidak membuat bising setelah pukul sepuluh malam.","faru","agar"]],
"g|eo|C2|Preposisi je (Serbaguna)":[["Ni renkontiĝos je la oka.","","Kita akan bertemu pada pukul delapan.","je la oka","pada"],["Ni malfruis je horo.","","Kami terlambat satu jam.","je horo",""],["Li aĉetis la domon je favora prezo.","","Dia membeli rumah itu dengan harga yang menguntungkan.","je favora","dengan"],["Ŝi ridis je mia ŝerco.","","Dia menertawakan leluconku.","je mia",""],["Li ricevis premion je mil eŭroj.","","Dia menerima hadiah sebesar seribu euro.","je mil","sebesar"],["Je mia surprizo, la pordo estis malfermita.","","Yang mengejutkanku, pintunya terbuka.","Je mia","mengejutkanku"],["Je la nomo de la ĉielo, diru al mi la veron!","","Demi nama langit, katakan yang sebenarnya padaku!","Je la nomo","Demi"],["La rivero estas larĝa je dudek metroj.","","Sungai itu lebarnya dua puluh meter.","je dudek",""],["Li estas pli aĝa ol mi je tri jaroj.","","Dia lebih tua tiga tahun dariku.","je tri",""],["Je kiu horo malfermiĝas la muzeo?","","Pukul berapa museum dibuka?","Je kiu horo","Pukul berapa"],["Je tri metroj de la pordo staras granda arbo.","","Pada jarak tiga meter dari pintu berdiri sebuah pohon besar.","Je tri","Pada jarak"],["Ni pagas la lupreton je la fino de la monato.","","Kami membayar sewa pada akhir bulan.","je la fino","pada"],["Je tiu rapideco la aŭto bezonos nur du horojn por atingi la urbon.","","Dengan kecepatan itu mobil hanya butuh dua jam untuk sampai ke kota.","Je tiu rapideco","Dengan"],["Je lia granda ĝojo, la filino ricevis stipendion.","","Yang sangat menggembirakannya, putrinya menerima beasiswa.","Je lia granda","menggembirakannya"],["La tago komenciĝas je la sunleviĝo kaj finiĝas je la sunsubiro.","","Hari dimulai saat matahari terbit dan berakhir saat matahari terbenam.","je la sunleviĝo","saat"]],
"g|eo|C2|Akhiran -op- (Kelompok Bilangan)":[["Ni iris duope al la kino.","","Kami pergi berdua ke bioskop.","duope","berdua"],["La infanoj eniris la ĉambron triope.","","Anak-anak masuk ke ruangan bertiga.","triope","bertiga"],["Ili venis nur duope, sen la gepatroj.","","Mereka datang hanya berdua, tanpa orang tuanya.","duope","berdua"],["La studentoj laboris triope por la projekto.","","Para mahasiswa mengerjakan proyek itu bertiga.","triope","bertiga"],["Ni ludis kartojn kvarope ĉe la tablo.","","Kami bermain kartu berempat di meja.","kvarope","berempat"],["Ili eliris el la domo sespope.","","Mereka keluar dari rumah berenam.","sespope","berenam"],["Ni facile levis la grandan tablon kvinope.","","Kami dengan mudah mengangkat meja besar itu berlima.","kvinope","berlima"],["Bonvolu eniri unuope, ne ĉiuj samtempe.","","Silakan masuk satu per satu, jangan semua serentak.","unuope","satu per satu"],["La soldatoj marŝis kvarope tra la strato.","","Para prajurit berbaris berempat di sepanjang jalan.","kvarope","berempat"],["Ni iris naŭope al la montaro per unu aŭtobuso.","","Kami pergi bersembilan ke pegunungan dengan satu bus.","naŭope","bersembilan"],["La ĉefo petis, ke ni sidiĝu okope ĉe la longa tablo.","","Atasan meminta agar kami duduk berdelapan di meja panjang itu.","okope","berdelapan"],["Ili laboris dekope en la malgranda oficejo.","","Mereka bekerja sepuluh orang di kantor kecil itu.","dekope","sepuluh orang"],["Dum la ekskurso ni dormis duope en ĉiu ĉambro de la gastejo.","","Selama tamasya kami tidur berdua di setiap kamar penginapan.","duope","berdua"],["Ŝi ne volis lasi la infanojn iri sepope tra la arbaro nokte.","","Dia tidak mau membiarkan anak-anak berjalan bertujuh melewati hutan malam hari.","sepope","bertujuh"],["La ŝafoj iris dekope laŭ la vojo al la paŝtejo.","","Domba-domba berjalan sepuluh-sepuluh di sepanjang jalan menuju padang rumput.","dekope","sepuluh-sepuluh"]],
"g|eo|C2|Anak Kalimat Tujuan (por ke)":[["Mi laboras, por ke vi studu.","","Saya bekerja supaya kamu bisa belajar.","por ke","supaya"],["Ŝi kantas laŭte, por ke ĉiuj aŭdu.","","Dia bernyanyi keras supaya semua mendengar.","por ke","supaya"],["Mi skribas klare, por ke li komprenu.","","Saya menulis dengan jelas supaya dia mengerti.","por ke","supaya"],["Ni haltis, por ke la infanoj ripozu.","","Kami berhenti supaya anak-anak beristirahat.","por ke","supaya"],["Li fermis la pordon, por ke neniu enŝteliĝu.","","Dia menutup pintu supaya tak seorang pun menyelinap masuk.","por ke","supaya"],["Mi aĉetis kaĝon, por ke la birdo ne forflugu.","","Saya membeli sangkar supaya burung itu tidak terbang pergi.","por ke","supaya"],["La instruisto parolis malrapide, por ke ĉiuj komprenu.","","Guru berbicara pelan supaya semua mengerti.","por ke","supaya"],["Mi montris al li la vojon, por ke li ne perdiĝu.","","Saya menunjukkan jalan kepadanya supaya dia tidak tersesat.","por ke","supaya"],["Ŝi pakis varman manĝaĵon, por ke ni ne malsatu survoje.","","Dia mengemas makanan hangat supaya kami tidak kelaparan di jalan.","por ke","supaya"],["Ni sendis la invitojn frue, por ke la gastoj havu sufiĉe da tempo.","","Kami mengirim undangan lebih awal supaya para tamu punya cukup waktu.","por ke","supaya"],["Li ŝparas monon, por ke liaj infanoj povu studi en universitato.","","Dia menabung supaya anak-anaknya dapat kuliah di universitas.","por ke","supaya"],["La urbo konstruis novan ponton, por ke la trafiko fluu pli glate.","","Kota membangun jembatan baru supaya lalu lintas mengalir lebih lancar.","por ke","supaya"],["Ili lumigis la tutan straton, por ke neniu timu promeni vespere.","","Mereka menerangi seluruh jalan supaya tak ada yang takut berjalan di malam hari.","por ke","supaya"],["Mi petis la kolegon helpi min, por ke ni finu la raporton antaŭ vendredo.","","Saya meminta rekan membantu saya supaya kami menyelesaikan laporan sebelum Jumat.","por ke","supaya"],["La registaro malaltigis la impostojn, por ke la ekonomio kreskiĝu kaj pli da homoj trovu laboron.","","Pemerintah menurunkan pajak supaya ekonomi tumbuh dan lebih banyak orang menemukan pekerjaan.","por ke","supaya"]],
"g|eo|C2|Akusatif Arah setelah Kata Benda Gerak":[["Lia reveno hejmen ĝojigis ĉiujn.","","Kepulangannya ke rumah menyenangkan semua orang.","hejmen","ke"],["Ŝia eniro en la salonon estis surpriza.","","Masuknya dia ke ruang tamu mengejutkan.","salonon","ke"],["Lia salto en la akvon estis bela.","","Lompatannya ke dalam air indah.","akvon","ke"],["La fuĝo en la arbaron savis ilin.","","Pelarian ke hutan menyelamatkan mereka.","arbaron","ke"],["Nia veturo Parizon daŭris ses horojn.","","Perjalanan kami ke Paris memakan waktu enam jam.","Parizon","ke"],["Mia vojaĝo Eŭropon estis tre longa.","","Perjalananku ke Eropa sangat panjang.","Eŭropon","ke"],["La marŝado supren daŭris tre longe.","","Pendakian ke atas berlangsung sangat lama.","supren","ke"],["La falo en la riveron okazis nokte.","","Jatuhnya ke sungai terjadi pada malam hari.","riveron","ke"],["Mi memoras vian saltadon en la lagon dum la ferio.","","Saya ingat lompatanmu ke danau saat liburan.","lagon","ke"],["Ŝia rapida kuro en la ĝardenon kaŭzis ridon.","","Larinya yang cepat ke taman memancing tawa.","ĝardenon","ke"],["Post nia migrado norden la vetero fariĝis pli malvarma.","","Setelah migrasi kami ke utara cuaca menjadi lebih dingin.","norden","ke"],["La fluo de la rivero en la maron estas konstanta tie.","","Aliran sungai ke laut di sana konstan.","maron","ke"],["Ĉiu veturo en la ĉefurbon estis aventuro por la knabo.","","Setiap perjalanan ke ibu kota adalah petualangan bagi anak itu.","ĉefurbon","ke"],["Ilia enmigrado Aŭstralion komenciĝis en la jaro mil naŭcent kvindek.","","Imigrasi mereka ke Australia dimulai pada tahun seribu sembilan ratus lima puluh.","Aŭstralion","ke"],["La forflugo suden de la birdoj anoncas la finon de la somero.","","Terbangnya burung-burung ke selatan menandai berakhirnya musim panas.","suden","ke"]],
"g|eo|C2|Akusatif setelah Kata Kerja Intransitif":[["Ŝi dormis profundan dormon.","","Dia tidur dengan sangat lelap.","dormon",""],["La infano ridis gajan ridon.","","Anak itu tertawa riang.","ridon",""],["Li vivis feliĉan vivon en la vilaĝo.","","Dia menjalani hidup bahagia di desa.","vivon",""],["La sportisto kuris rapidan kuron.","","Atlet itu berlari dengan cepat.","kuron",""],["Ŝi ridetis kaŝeman rideton.","","Dia tersenyum diam-diam.","rideton",""],["La infano ploris amarajn larmojn.","","Anak itu menangis dengan air mata pahit.","larmojn",""],["Ili dancis lertan dancon.","","Mereka menari dengan lincah.","dancon",""],["Mi pensis tre malĝojajn pensojn.","","Saya memikirkan pikiran yang sangat sedih.","pensojn",""],["La avo sonĝis strangan sonĝon hieraŭ nokte.","","Kakek bermimpi aneh tadi malam.","sonĝon",""],["Ŝi kriis teruran krion, kiam ŝi vidis la araneon.","","Dia menjerit ngeri ketika melihat laba-laba itu.","krion",""],["Li luktis longan lukton kontraŭ la malsano.","","Dia berjuang lama melawan penyakit itu.","lukton",""],["Ŝi vivis duoblan vivon kaj neniu sciis pri tio.","","Dia menjalani kehidupan ganda dan tak seorang pun tahu.","vivon",""],["La infanoj ludis gajan ludon en la korto.","","Anak-anak bermain permainan seru di halaman.","ludon",""],["Post longa tago mi dormis senzorgan dormon.","","Setelah hari yang panjang saya tidur tanpa beban.","dormon",""],["Sur la scenejo ŝi kantis kaj dancis sian lastan dancon.","","Di atas panggung dia bernyanyi dan menari tarian terakhirnya.","dancon",""]],
"g|eo|C2|Akusatif setelah Kata Kerja Pilihan":[["Mi pardonas lin.","","Saya memaafkannya.","lin",""],["Ŝi pardonis al mi la eraron.","","Dia memaafkan kesalahanku.","al mi",""],["La hundo obeas sian mastron.","","Anjing itu menurut pada tuannya.","sian mastron",""],["Mi dankas vin pro la donaco.","","Saya berterima kasih padamu atas hadiah itu.","vin",""],["La soldatoj servis la landon dum multaj jaroj.","","Para prajurit mengabdi pada negara bertahun-tahun.","la landon",""],["La infanoj ne obeis al la patro.","","Anak-anak tidak menurut kepada ayah.","al la patro",""],["Mi kredas lin, ĉar li neniam mensogis.","","Saya memercayainya karena dia tak pernah berbohong.","lin",""],["Li helpis al la maljunulino porti la sakon.","","Dia membantu nenek itu membawa tas.","al la maljunulino",""],["Bonvolu pardoni nin, ni ne volis ĝeni vin.","","Mohon maafkan kami, kami tidak bermaksud mengganggumu.","nin",""],["Ni adiaŭis niajn gastojn ĉe la pordo.","","Kami mengucapkan selamat tinggal kepada para tamu di pintu.","niajn gastojn",""],["Mi dankas al la tuta teamo pro la subteno.","","Saya berterima kasih kepada seluruh tim atas dukungannya.","al la tuta teamo",""],["La instruisto pardonis la knabon pro la unua eraro.","","Guru memaafkan anak laki-laki itu atas kesalahan pertamanya.","la knabon",""],["La kuracisto helpis la vunditan viron kaj poste kuracis lin.","","Dokter menolong pria yang terluka lalu mengobatinya.","la vunditan viron",""],["Mi apenaŭ povas kredi al miaj oreloj.","","Saya hampir tak percaya pada telingaku sendiri.","al miaj oreloj",""],["La nova ŝtatestro promesis servi al la popolo, ne al si mem.","","Kepala negara baru berjanji melayani rakyat, bukan dirinya sendiri.","al la popolo",""]],
"g|eo|C2|Akusatif setelah Adverbia Tertentu":[["Rilate tion mi ne havas opinion.","","Berkaitan dengan itu saya tidak punya pendapat.","tion","Berkaitan dengan"],["Koncerne tion, ni jam decidis.","","Mengenai hal itu, kami sudah memutuskan.","tion","Mengenai"],["Koncerne la aferon, ni parolos morgaŭ.","","Mengenai urusan itu, kita akan bicara besok.","la aferon","Mengenai"],["Koncerne la veteron, mi ne zorgas.","","Mengenai cuaca, saya tidak peduli.","la veteron","Mengenai"],["Rilate la prezon, ni ankoraŭ negocas.","","Berkaitan dengan harga, kami masih bernegosiasi.","la prezon","Berkaitan dengan"],["Koncerne la kostojn, la komitato ankoraŭ ne decidis.","","Mengenai biaya, panitia belum memutuskan.","la kostojn","Mengenai"],["Rilate lian sanon mi estas tre optimisma.","","Berkaitan dengan kesehatannya saya sangat optimis.","lian sanon","Berkaitan dengan"],["Koncerne vian peton, ni donos respondon baldaŭ.","","Mengenai permintaan Anda, kami akan memberi jawaban segera.","vian peton","Mengenai"],["Rilate la vojaĝon, mi jam aĉetis la biletojn.","","Berkaitan dengan perjalanan itu, saya sudah membeli karcisnya.","la vojaĝon","Berkaitan dengan"],["Koncerne la historion de tiu urbo, oni scias nur malmulton.","","Mengenai sejarah kota itu, orang hanya tahu sedikit.","la historion","Mengenai"],["Rilate la novajn regulojn, la estro faros anoncon.","","Berkaitan dengan peraturan baru, atasan akan membuat pengumuman.","la novajn regulojn","Berkaitan dengan"],["Koncerne mian lastan leteron, mi ankoraŭ atendas vian respondon.","","Mengenai surat terakhirku, saya masih menunggu jawabanmu.","mian lastan leteron","Mengenai"],["Rilate la solvon de la problemo, ĉiuj havis siajn ideojn.","","Berkaitan dengan solusi masalah itu, semua punya gagasan sendiri.","la solvon","Berkaitan dengan"],["Rilate la nombron de la partoprenantoj, ni bezonas pli precizajn datumojn.","","Berkaitan dengan jumlah peserta, kami butuh data yang lebih tepat.","la nombron","Berkaitan dengan"],["Rilate la aferon de la mono, la direktoro rifuzis komenti.","","Berkaitan dengan soal uang itu, direktur menolak berkomentar.","la aferon","Berkaitan dengan"]],
"g|eo|C2|Akhiran -um- (Tak Tentu)":[["Mi aerumas la ĉambron.","","Saya menganginkan ruangan.","aerumas","menganginkan"],["Ŝi akvumis la florojn.","","Dia menyiram bunga-bunga.","akvumis","menyiram"],["Li ventumas sin per revuo.","","Dia mengipasi dirinya dengan majalah.","ventumas","mengipasi"],["Li plenumis sian promeson.","","Dia memenuhi janjinya.","plenumis","memenuhi"],["Mi foliumis la libron, sed ne legis ĝin.","","Saya membolak-balik buku itu, tetapi tidak membacanya.","foliumis","membolak-balik"],["Bonvolu gustumi la supon antaŭ ol aldoni salon.","","Silakan cicipi sup itu sebelum menambahkan garam.","gustumi","cicipi"],["La patrino brakumis sian filon fervore.","","Sang ibu memeluk putranya dengan hangat.","brakumis","memeluk"],["Ni bezonas aerumi la salonon post la festo.","","Kita perlu menganginkan ruang tamu setelah pesta.","aerumi","menganginkan"],["Ĉiun matenon la ĝardenisto akvumas la rozojn.","","Setiap pagi tukang kebun menyiram mawar.","akvumas","menyiram"],["Ĉiu devas plenumi siajn devojn kaj respekti la leĝojn.","","Setiap orang harus memenuhi kewajibannya dan menghormati hukum.","plenumi","memenuhi"],["Dum atendado en la kuracejo mi foliumis malnovajn revuojn.","","Sambil menunggu di klinik saya membolak-balik majalah lama.","foliumis","membolak-balik"],["La sommeliero gustumis la vinon kaj ridetis kontente.","","Sommelier itu mencicipi anggur itu dan tersenyum puas.","gustumis","mencicipi"],["Post longa disiĝo la fratinoj brakumis sin kaj ploris.","","Setelah lama berpisah, kedua saudari itu berpelukan dan menangis.","brakumis","berpelukan"],["La registaro plenumis la promeson donitan antaŭ la elektoj.","","Pemerintah memenuhi janji yang diberikan sebelum pemilu.","plenumis","memenuhi"],["En la varma tago la turistoj ventumis sin per paperaj ventumiloj.","","Di hari yang panas para turis mengipasi diri dengan kipas kertas.","ventumis","mengipasi"]],
"g|eo|C2|Izin (Permesi, Lasi, Imperatif)":[["Mi permesas, ke vi restu.","","Saya mengizinkan kamu tinggal.","permesas","mengizinkan"],["Permesu, ke mi prezentu min.","","Izinkan saya memperkenalkan diri.","Permesu","Izinkan"],["Ĉu vi permesos al mi uzi vian telefonon?","","Apakah kamu akan mengizinkan saya memakai ponselmu?","permesos","mengizinkan"],["Permesu al mi helpi vin porti la valizon.","","Izinkan saya membantumu membawa koper.","Permesu","Izinkan"],["La patro ne permesis, ke ni ludu ekstere.","","Ayah tidak mengizinkan kami bermain di luar.","permesis","mengizinkan"],["La instruisto permesis al ni forlasi la klason pli frue.","","Guru mengizinkan kami meninggalkan kelas lebih awal.","permesis","mengizinkan"],["La leĝo ne permesas, ke infanoj veturu sen sekurzono.","","Hukum tidak mengizinkan anak-anak berkendara tanpa sabuk pengaman.","permesas","mengizinkan"],["Mia estro permesis, ke mi laboru hejme ĉi tiun semajnon.","","Atasan saya mengizinkan saya bekerja dari rumah minggu ini.","permesis","mengizinkan"],["Mi ne permesos al iu ajn paroli tiel pri mia familio.","","Saya tidak akan mengizinkan siapa pun berbicara begitu tentang keluargaku.","permesos","mengizinkan"],["La kuracisto permesis al la paciento iom promeni en la ĝardeno.","","Dokter mengizinkan pasien itu berjalan-jalan sebentar di taman.","permesis","mengizinkan"],["La gepatroj ne permesis al la filino vojaĝi sola tiel malproksimen.","","Orang tua tidak mengizinkan putrinya bepergian sendirian sejauh itu.","permesis","mengizinkan"],["Se vi permesos, ke mi parolu malferme, mi diros mian opinion.","","Jika kamu mengizinkan saya berbicara terus terang, saya akan menyampaikan pendapat saya.","permesos","mengizinkan"],["La urbestro permesis al la artistoj ekspozicii sur la placo dum la tuta somero.","","Wali kota mengizinkan para seniman berpameran di alun-alun sepanjang musim panas.","permesis","mengizinkan"],["Ni petas, ke la direkcio permesu al ni uzi la salonon por la kunveno.","","Kami meminta agar pimpinan mengizinkan kami memakai aula untuk rapat.","permesu","mengizinkan"]],
"g|eo|C2|Izin dengan lasi":[["Lasu lin veni.","","Biarkan dia datang.","Lasu","Biarkan"],["Lasu min pensi unu minuton.","","Biarkan saya berpikir satu menit.","Lasu","Biarkan"],["Ŝi ne lasis min paroli.","","Dia tidak membiarkan saya berbicara.","lasis","membiarkan"],["Mi lasos vin decidi mem.","","Saya akan membiarkan kamu memutuskan sendiri.","lasos","membiarkan"],["La patrino lasis la infanojn ludi ekstere.","","Ibu membiarkan anak-anak bermain di luar.","lasis","membiarkan"],["Ne lasu la hundon eniri la kuirejon.","","Jangan biarkan anjing itu masuk ke dapur.","lasu","biarkan"],["Li lasis la akvon flui tutan nokton.","","Dia membiarkan air mengalir sepanjang malam.","lasis","membiarkan"],["La instruisto lasis la lernantojn elekti la temon.","","Guru membiarkan murid memilih tema.","lasis","membiarkan"],["Ŝi lasis la teon malvarmiĝi kaj forgesis ĝin.","","Dia membiarkan teh itu dingin dan melupakannya.","lasis","membiarkan"],["Ne lasu vin trompi de tiaj promesoj.","","Jangan biarkan dirimu tertipu oleh janji-janji seperti itu.","lasu","biarkan"],["La gardisto ne lasis nin eniri la muzeon sen biletoj.","","Penjaga tidak membiarkan kami masuk museum tanpa karcis.","lasis","membiarkan"],["Li lasis sin konvinki, ke la plano estas bona.","","Dia membiarkan dirinya diyakinkan bahwa rencana itu bagus.","lasis","membiarkan"],["La estro ne lasis la dungitojn foriri antaŭ la fino de la kunveno.","","Atasan tidak membiarkan karyawan pergi sebelum rapat selesai.","lasis","membiarkan"],["Mia avino lasas siajn nepojn manĝi dolĉaĵojn kiom ili volas.","","Nenek saya membiarkan cucu-cucunya makan permen sebanyak yang mereka mau.","lasas","membiarkan"],["Se vi lasos la knabon fari ĉion, kion li volas, li neniam lernos obei.","","Jika kamu membiarkan anak itu berbuat sesukanya, dia tak akan pernah belajar menurut.","lasos","membiarkan"]],
"g|eo|C2|Izin dengan Imperatif":[["Ĉu mi eniru?","","Bolehkah saya masuk?","eniru","Bolehkah"],["Ĉu ni komencu nun?","","Bolehkah kita mulai sekarang?","komencu","Bolehkah"],["Ĉu mi sidiĝu ĉi tie?","","Bolehkah saya duduk di sini?","sidiĝu","Bolehkah"],["Ĉu mi malfermu la fenestron?","","Bolehkah saya membuka jendela?","malfermu","Bolehkah"],["Ĉu mi demandu vin ion?","","Bolehkah saya menanyakan sesuatu padamu?","demandu","Bolehkah"],["Ĉu mi telefonu vin poste?","","Bolehkah saya meneleponmu nanti?","telefonu","Bolehkah"],["Ĉu mi eniru? — Jes, envenu!","","Bolehkah saya masuk? — Ya, silakan masuk!","eniru","Bolehkah"],["Ĉu mi prenu unu pli da kuko?","","Bolehkah saya mengambil sepotong kue lagi?","prenu","Bolehkah"],["Ĉu mi ŝaltu la lumon? — Jes, bonvolu.","","Bolehkah saya menyalakan lampu? — Ya, silakan.","ŝaltu","Bolehkah"],["Ĉu mi foriru nun? — Ne, restu ankoraŭ iomete.","","Bolehkah saya pergi sekarang? — Jangan, tinggallah sebentar lagi.","foriru","Bolehkah"],["Ĉu mi fotu vin kune kun viaj gefratoj?","","Bolehkah saya memotret kamu bersama saudara-saudaramu?","fotu","Bolehkah"],["Panjo, ĉu mi uzu la aŭton hodiaŭ vespere? — Jes, prenu la ŝlosilojn.","","Ibu, bolehkah saya memakai mobil malam ini? — Ya, ambillah kuncinya.","uzu","Bolehkah"],["Ĉu mi ordonu la vinon, aŭ ĉu vi preferas mem elekti?","","Bolehkah saya memesan anggurnya, atau kamu lebih suka memilih sendiri?","ordonu","Bolehkah"],["Ĉu mi aliĝu al via grupo por la vespermanĝo, aŭ ĉu ĝi estas privata?","","Bolehkah saya bergabung dengan kelompokmu untuk makan malam, atau itu privat?","aliĝu","Bolehkah"],["Ĉu mi enlasu la gastojn nun, aŭ ĉu vi preferas atendi ankoraŭ iomete?","","Bolehkah saya mempersilakan para tamu masuk sekarang, atau kamu lebih suka menunggu sebentar lagi?","enlasu","Bolehkah"]],
"g|eo|C2|Kemungkinan dan Probabilitas":[["Eble li venos morgaŭ.","","Mungkin dia akan datang besok.","Eble","Mungkin"],["Eble pluvos hodiaŭ posttagmeze.","","Mungkin sore ini akan hujan.","Eble","Mungkin"],["Ŝi eble forgesis la rendevuon.","","Dia mungkin lupa pada janji temu.","eble","mungkin"],["Ni eble iros al la maro dum la ferio.","","Kami mungkin akan pergi ke laut saat liburan.","eble","mungkin"],["Mia frato eble scias la respondon.","","Kakak saya mungkin tahu jawabannya.","eble","mungkin"],["La butiko eble estas jam fermita.","","Tokonya mungkin sudah tutup.","eble","mungkin"],["Vi eble pravas, sed mi ankoraŭ dubas.","","Kamu mungkin benar, tetapi saya masih ragu.","eble","mungkin"],["Eble la trajno malfruos pro la neĝo.","","Mungkin kereta akan terlambat karena salju.","Eble","Mungkin"],["Eble mi vizitos vin dimanĉe, se mi havos tempon.","","Mungkin saya akan mengunjungimu hari Minggu, jika punya waktu.","Eble","Mungkin"],["Li eble ne aŭdis la telefonon, ĉar li dormis.","","Dia mungkin tidak mendengar telepon karena tidur.","eble","mungkin"],["Eble ŝi simple ne volis paroli pri tio antaŭ la aliaj.","","Mungkin dia hanya tidak ingin membicarakannya di depan yang lain.","Eble","Mungkin"],["Eble vi ne memoras min, sed ni konatiĝis antaŭ dek jaroj.","","Mungkin kamu tidak ingat saya, tetapi kita berkenalan sepuluh tahun lalu.","Eble","Mungkin"],["La polico eble ankoraŭ ne scias, kiu ŝtelis la bildon.","","Polisi mungkin belum tahu siapa yang mencuri lukisan itu.","eble","mungkin"],["Ni eble trovos taŭgan loĝejon en la centro, sed ĝi estos multekosta.","","Kami mungkin menemukan tempat tinggal yang cocok di pusat kota, tetapi akan mahal.","eble","mungkin"],["La novaj reguloj eble helpos, sed neniu povas esti certa antaŭ la fino de la jaro.","","Peraturan baru mungkin akan membantu, tetapi tak seorang pun bisa yakin sebelum akhir tahun.","eble","mungkin"]],
"g|eo|C2|Probabilitas dengan kredeble, verŝajne":[["Kredeble li sukcesos.","","Kemungkinan besar dia akan berhasil.","Kredeble","Kemungkinan besar"],["Verŝajne ĝi pluvos morgaŭ.","","Kemungkinan besar besok akan hujan.","Verŝajne","Kemungkinan besar"],["Li verŝajne jam foriris.","","Dia kemungkinan besar sudah pergi.","verŝajne","kemungkinan besar"],["Ŝi kredeble estas hejme nun.","","Dia kemungkinan besar ada di rumah sekarang.","kredeble","kemungkinan besar"],["La kunveno kredeble daŭros du horojn.","","Rapat itu kemungkinan besar berlangsung dua jam.","kredeble","kemungkinan besar"],["Verŝajne mi ne povos veni vendredon.","","Kemungkinan besar saya tak bisa datang hari Jumat.","Verŝajne","Kemungkinan besar"],["Ni kredeble ricevos la respondon ĉi-semajne.","","Kami kemungkinan besar akan menerima jawaban minggu ini.","kredeble","kemungkinan besar"],["La prezoj verŝajne altiĝos jam venontmonate.","","Harga kemungkinan besar naik bulan depan.","verŝajne","kemungkinan besar"],["Mia fratino kredeble havas ankoraŭ la ŝlosilon.","","Adik perempuan saya kemungkinan besar masih punya kuncinya.","kredeble","kemungkinan besar"],["Kredeble la tuta afero estas nur miskompreno.","","Kemungkinan besar seluruh persoalan hanyalah salah paham.","Kredeble","Kemungkinan besar"],["La teamo verŝajne gajnos, ĉar ĝi ludas pli bone ol la aliaj.","","Tim itu kemungkinan besar menang karena bermain lebih baik daripada yang lain.","verŝajne","kemungkinan besar"],["Li kredeble nenion diros, se oni ne demandos lin rekte.","","Dia kemungkinan besar tidak akan berkata apa pun jika tidak ditanya langsung.","kredeble","kemungkinan besar"],["Verŝajne la vojo estos fermita pro la laboroj, do ni elektu alian.","","Kemungkinan besar jalan ditutup karena pekerjaan jalan, jadi kita pilih jalan lain.","Verŝajne","Kemungkinan besar"],["Ŝi kredeble ne scias, ke ŝia amikino translokiĝis al alia urbo.","","Dia kemungkinan besar tak tahu bahwa temannya pindah ke kota lain.","kredeble","kemungkinan besar"],["La ekonomio verŝajne kreskos denove, kvankam la antaŭvidoj ne estas tute certaj.","","Ekonomi kemungkinan besar tumbuh lagi, meskipun prakiraan tidak sepenuhnya pasti.","verŝajne","kemungkinan besar"]],
"g|eo|C2|Awalan ge- (Kedua Jenis Kelamin)":[["Miaj gepatroj loĝas en Bandung.","","Orang tua saya tinggal di Bandung.","gepatroj","Orang tua"],["Ŝiaj gefratoj studas eksterlande.","","Kakak-adiknya belajar di luar negeri.","gefratoj","Kakak-adiknya"],["Bonan vesperon, gesinjoroj!","","Selamat malam, Tuan-tuan dan Nyonya-nyonya!","gesinjoroj","Tuan-tuan dan Nyonya-nyonya"],["Niaj geavoj envenos hodiaŭ vespere.","","Kakek dan nenek kami datang malam ini.","geavoj","Kakek dan nenek"],["La geedzoj Kovalski festis sian dudekan datrevenon.","","Pasangan suami istri Kovalski merayakan ulang tahun pernikahan ke-20.","geedzoj","suami istri"],["Ĉiuj geknaboj en la klaso ricevis donacon.","","Semua anak laki-laki dan perempuan di kelas menerima hadiah.","geknaboj","anak laki-laki dan perempuan"],["Miaj gekuzoj vivas en malsamaj landoj.","","Sepupu-sepupu saya, laki-laki dan perempuan, tinggal di negara yang berbeda.","gekuzoj","Sepupu-sepupu"],["La gepatroj de la knabino promesis atendi ŝin antaŭ la lernejo.","","Orang tua gadis itu berjanji menunggunya di depan sekolah.","gepatroj","Orang tua"],["Ŝi havas du gefilojn: filon kaj filinon.","","Dia punya dua anak: seorang putra dan seorang putri.","gefilojn","anak"],["La geamikoj de nia filo ofte ludas en nia ĝardeno.","","Teman laki-laki dan perempuan putra kami sering bermain di kebun kami.","geamikoj","teman laki-laki dan perempuan"],["La gelernantoj de nia lernejo partoprenis la ekskurson.","","Para murid laki-laki dan perempuan di sekolah kami ikut tamasya.","gelernantoj","murid"],["Ni invitis ĉiujn gefratojn de mia edzino al la festo.","","Kami mengundang semua saudara laki-laki dan perempuan istri saya ke pesta.","gefratojn","saudara laki-laki dan perempuan"],["La geinstruistoj kunsidis por decidi pri la novaj horaroj.","","Para guru laki-laki dan perempuan bersidang untuk memutuskan jadwal baru.","geinstruistoj","guru"],["Dum la konferenco la gekolegoj de ĉiuj landoj konatiĝis.","","Selama konferensi, rekan kerja laki-laki dan perempuan dari semua negara berkenalan.","gekolegoj","rekan kerja"],["Ni salutas la gesinjorojn kaj dankas ilin pro la ĉeesto.","","Kami menyapa Tuan-tuan dan Nyonya-nyonya serta berterima kasih atas kehadiran mereka.","gesinjorojn","Tuan-tuan dan Nyonya-nyonya"]],
"g|eo|C2|Akhiran -aĉ- (Merendahkan)":[["Kia veteraĉo hodiaŭ!","","Cuaca buruk sekali hari ini!","veteraĉo","buruk"],["Ili loĝas en malgranda domaĉo.","","Mereka tinggal di gubuk kecil.","domaĉo","gubuk"],["Foriru de ĉi tie, vi hundaĉo!","","Pergi dari sini, dasar anjing!","hundaĉo","dasar anjing"],["Mi ne ŝatas tiun libraĉon.","","Saya tidak suka buku murahan itu.","libraĉon","murahan"],["La popolaĉo kriis sur la strato.","","Rakyat jelata berteriak di jalan.","popolaĉo","jelata"],["Tiu manĝaĉo estis preskaŭ nemanĝebla.","","Makanan jelek itu nyaris tak bisa dimakan.","manĝaĉo","jelek"],["Li loĝas en ĉambraĉo sen fenestro.","","Dia tinggal di kamar sempit yang kumuh tanpa jendela.","ĉambraĉo","kumuh"],["Mi ne komprenas tiun filmaĉon pri kosmo.","","Saya tidak mengerti film murahan tentang luar angkasa itu.","filmaĉon","murahan"],["Mi devis trinki malvarman kafaĉon en la stacidomo.","","Saya harus minum kopi dingin yang tak enak di stasiun.","kafaĉon","tak enak"],["Tiu vortaĉo ne decas en la buŝo de bone edukita homo.","","Kata kasar itu tidak pantas di mulut orang berpendidikan.","vortaĉo","kasar"],["Ni vidis ĉevalaĉon, kiu apenaŭ povis stari sur siaj kruroj.","","Kami melihat kuda kurus yang hampir tak bisa berdiri di atas kakinya.","ĉevalaĉon","kuda kurus"],["Ili finfine vendis sian malnovan aŭtaĉon por kelkaj eŭroj.","","Mereka akhirnya menjual mobil rongsoknya seharga beberapa euro.","aŭtaĉon","rongsok"],["Ŝi estas bona kantistino, sed ŝia vestaĉo ne taŭgis por la koncerto.","","Dia penyanyi yang baik, tetapi pakaian lusuhnya tidak cocok untuk konser.","vestaĉo","lusuh"],["Mi laŭte plendis pri la lernejaĉo, kie la tegmento fluas.","","Saya mengeluh keras tentang sekolah bobrok itu, tempat atapnya bocor.","lernejaĉo","bobrok"],["Post la tuta tago en la pluvo ni alvenis en la gastejaĉon malsataj kaj malsekaj.","","Setelah seharian dalam hujan, kami tiba di penginapan murahan, lapar dan basah.","gastejaĉon","murahan"]],
"g|eo|C2|Interjeksi":[["Hura, ni gajnis la ludon!","","Hore, kita menang pertandingan!","Hura","Hore"],["Hura por la naskiĝtaga infano!","","Hore untuk anak yang berulang tahun!","Hura","Hore"],["Ho, kiel bela estas la maro!","","Oh, betapa indahnya laut!","Ho","Oh"],["Fi, kiel malbone ĝi odoras!","","Cih, betapa busuknya baunya!","Fi","Cih"],["Nu, ni iru nun.","","Nah, mari kita pergi sekarang.","Nu","Nah"],["Ve, kiom mi bedaŭras tion!","","Aduh, betapa saya menyesalinya!","Ve","Aduh"],["Ho ve, mi perdis mian monujon!","","Aduh celaka, saya kehilangan dompetku!","Ho ve","Aduh celaka"],["Nu, kion vi volas diri per tio?","","Nah, apa maksudmu dengan itu?","Nu","Nah"],["Adiaŭ, mia amiko, ni revidos nin iam!","","Selamat tinggal, temanku, kita akan bertemu lagi suatu hari!","Adiaŭ","Selamat tinggal"],["Fi al la mensogulo, kiu trompis nin ĉiujn!","","Cih, pembohong yang menipu kita semua!","Fi","Cih"],["Ek, ni ne perdu tempon, la trajno ne atendos nin!","","Ayo, kita jangan buang waktu, kereta tidak akan menunggu kita!","Ek","Ayo"],["Ho, mi tute forgesis, ke hodiaŭ estas lundo!","","Oh, saya benar-benar lupa kalau hari ini Senin!","Ho","Oh"],["Ve, la tuta rikolto estas detruita de la hajlo!","","Aduh, seluruh panen hancur oleh hujan es!","Ve","Aduh"],["Hura! kriis la knaboj, kiam la fina bato eniris la golejon.","","Hore! teriak anak-anak ketika tendangan terakhir masuk ke gawang.","Hura","Hore"],["Adiaŭ, ni diris sur la kajo, kaj la ŝipo malproksimiĝis en la nebulo.","","Selamat tinggal, kata kami di dermaga, dan kapal menjauh dalam kabut.","Adiaŭ","Selamat tinggal"]],
"g|eo|C2|Posisi Pronomo Tak Bertekanan":[["Mi volas lin vidi.","","Saya ingin melihat dia.","lin vidi",""],["Ŝi ne povas ĝin trovi.","","Dia tidak bisa menemukannya.","ĝin trovi",""],["Ni devas ilin helpi.","","Kita harus membantu mereka.","ilin helpi",""],["Mi ne volas ĝin manĝi.","","Saya tidak mau memakannya.","ĝin manĝi",""],["Li kuraĝis ŝin inviti al la danco.","","Dia berani mengajaknya ke dansa.","ŝin inviti",""],["Ŝi provis min konvinki, sed vane.","","Dia mencoba meyakinkan saya, tetapi sia-sia.","min konvinki",""],["Mi ne ŝatus vin ĝeni.","","Saya tidak ingin mengganggumu.","vin ĝeni",""],["Mi esperas lin renkonti ĉe la stacidomo.","","Saya berharap bertemu dengannya di stasiun.","lin renkonti",""],["La kuracisto bezonas vin ekzameni denove.","","Dokter perlu memeriksamu lagi.","vin ekzameni",""],["Ni ne havas tempon ĝin ripari hodiaŭ.","","Kita tidak punya waktu memperbaikinya hari ini.","ĝin ripari",""],["Ŝi ne intencis ilin ofendi per tiu rimarko.","","Dia tidak bermaksud menyinggung mereka dengan komentar itu.","ilin ofendi",""],["Li petis min lin akompani al la flughaveno.","","Dia memintaku menemaninya ke bandara.","lin akompani",""],["Ni ĉiuj promesis ŝin viziti ĉiumonate.","","Kami semua berjanji mengunjunginya setiap bulan.","ŝin viziti",""],["Ni ne havas kialon ilin dubi, ĉar ili ĉiam diris la veron.","","Kita tak punya alasan meragukan mereka, karena mereka selalu berkata jujur.","ilin dubi",""],["Mi ne scias, kiel mi povus ilin danki por la tuta helpo, kiun ili donis al ni.","","Saya tidak tahu bagaimana saya bisa berterima kasih kepada mereka atas semua bantuan yang mereka berikan.","ilin danki",""]],
"g|eo|C2|Kata Kerja Intransitif yang Dijadikan Transitif":[["Li boligas la akvon.","","Dia mendidihkan air.","boligas",""],["Ŝi bruligis la leteron.","","Dia membakar surat itu.","bruligis",""],["La pluvo kreskigis la herbon.","","Hujan menumbuhkan rumput.","kreskigis",""],["La ludo ridigis ĉiujn.","","Permainan itu membuat semua orang tertawa.","ridigis",""],["Li falligis la vazon de la breto.","","Dia menjatuhkan vas dari rak.","falligis",""],["Ŝi sidigis la infanon sur la seĝon.","","Dia mendudukkan anak itu di kursi.","sidigis",""],["La suno sekigas la lavaĵon rapide.","","Matahari mengeringkan cucian dengan cepat.","sekigas",""],["La knabo ekdormigis la beboon.","","Anak laki-laki itu menidurkan bayi.","ekdormigis",""],["Mi ruligis la barelon laŭ la deklivo.","","Saya menggulirkan tong itu menuruni lereng.","ruligis",""],["La ŝoforo haltigis la aŭton antaŭ la pordo.","","Sopir menghentikan mobil di depan pintu.","haltigis",""],["La instruisto trankviligis la timemajn infanojn.","","Guru menenangkan anak-anak yang ketakutan.","trankviligis",""],["Ŝi plorigis la spektantojn per sia kanto.","","Dia membuat penonton menangis dengan lagunya.","plorigis",""],["La kuiristo frostigis la restaĵojn por la sekva semajno.","","Koki membekukan sisa makanan untuk minggu depan.","frostigis",""],["Per rapida movo li turnigis la radon kaj la maŝino ekfunkciis.","","Dengan gerakan cepat dia memutar roda itu dan mesin mulai bekerja.","turnigis",""],["La ĝojaj novaĵoj ekbriligis la okulojn de la maljunulino.","","Kabar gembira membuat mata sang nenek berbinar.","ekbriligis",""]],
"g|eo|C2|Akhiran -er- (Satuan Bagian)":[["Fajrero falis sur la tapiŝon.","","Percikan api jatuh ke atas karpet.","Fajrero","Percikan api"],["Ĉiu neĝero estas malsama.","","Setiap kepingan salju berbeda.","neĝero","kepingan salju"],["Polvero eniris mian okulon.","","Sebutir debu masuk ke mataku.","Polvero","debu"],["Eĉ unu panero ne restis sur la tablo.","","Satu remah roti pun tak tersisa di meja.","panero","remah roti"],["Mi trovis sablerojn en miaj ŝuoj.","","Saya menemukan butir-butir pasir di sepatu saya.","sablerojn","butir-butir pasir"],["La infano kolektis monerojn en kruĉo.","","Anak itu mengumpulkan koin dalam kendi.","monerojn","koin"],["La fajreroj de la kameno flugis tra la ĉambro.","","Percikan api dari perapian beterbangan di dalam ruangan.","fajreroj","Percikan api"],["Mi perdis unu ĉeneron de la kolĉeno.","","Saya kehilangan satu mata rantai dari kalung itu.","ĉeneron","mata rantai"],["Antaŭ la domo kreskis nur kelkaj herberoj.","","Di depan rumah hanya tumbuh beberapa helai rumput.","herberoj","helai rumput"],["Ŝi kalkulis ĉiun rizeron, ĉar malmulte restis.","","Dia menghitung setiap butir nasi karena hanya sedikit yang tersisa.","rizeron","butir nasi"],["Sub la mikroskopo oni povas distingi ĉiun sableron.","","Di bawah mikroskop orang bisa membedakan setiap butir pasir.","sableron","butir pasir"],["En la fenestro brilis neĝeroj, kiuj malrapide falis.","","Di jendela berkilau kepingan-kepingan salju yang jatuh perlahan.","neĝeroj","kepingan-kepingan salju"],["Li ne havis eĉ moneron en la poŝo, kiam li venis en la urbon.","","Dia tak punya sekeping koin pun di saku ketika datang ke kota.","moneron","koin"],["La ventego portis polverojn de la dezerto ĝis la urbo.","","Badai membawa butir-butir debu dari gurun sampai ke kota.","polverojn","butir-butir debu"],["Post la festeno la birdoj kolektis la panerojn el la herbo.","","Setelah pesta, burung-burung memungut remah-remah roti dari rumput.","panerojn","remah-remah roti"]],
"g|eo|C2|Awalan bo- dan duon- (Kekerabatan)":[["Mia bopatro loĝas en Medan.","","Ayah mertua saya tinggal di Medan.","bopatro","Ayah mertua"],["Ŝia bopatrino bone kuiras.","","Ibu mertuanya pandai memasak.","bopatrino","Ibu mertua"],["Mia bofrato estas kuracisto.","","Saudara ipar saya adalah dokter.","bofrato","ipar"],["Lia bofratino instruas en la lernejo.","","Saudari iparnya mengajar di sekolah.","bofratino","ipar"],["Nia bofilo helpas nin multe.","","Menantu laki-laki kami banyak membantu kami.","bofilo","Menantu"],["Ŝi vizitis sian bofilinon hieraŭ.","","Dia mengunjungi menantu perempuannya kemarin.","bofilinon","menantu"],["Dimanĉe mi manĝos kun miaj bogepatroj.","","Hari Minggu saya makan bersama mertua saya.","bogepatroj","mertua"],["Miaj bogepatroj aĉetis domon proksime al la maro.","","Mertua saya membeli rumah dekat laut.","bogepatroj","Mertua"],["La bopatrino de mia fratino ĉiam alportas dolĉaĵojn.","","Ibu mertua kakak saya selalu membawa kue manis.","bopatrino","Ibu mertua"],["Mia bopatro donis al mi bonan konsilon pri la domo.","","Ayah mertua saya memberi saya nasihat bagus tentang rumah itu.","bopatro","Ayah mertua"],["Li kaj lia bofrato kune malfermis malgrandan butikon.","","Dia dan saudara iparnya bersama-sama membuka toko kecil.","bofrato","ipar"],["Ŝia bofratino aranĝis la tutan geedziĝan feston.","","Saudari iparnya mengatur seluruh pesta pernikahan.","bofratino","ipar"],["Kiam ni translokiĝis, nia bofilo pruntedonis sian kamioneton.","","Ketika kami pindah, menantu laki-laki kami meminjamkan truknya.","bofilo","menantu"],["Ŝi tre amas sian bofilinon, kvazaŭ ŝi estus ŝia propra filino.","","Dia sangat menyayangi menantu perempuannya, seolah-olah dia putrinya sendiri.","bofilinon","menantu"],["Mia edzino kaj mia bofrato ofte kverelas, sed ili ankaŭ tre amas unu la alian.","","Istri saya dan saudara ipar saya sering bertengkar, tetapi mereka juga saling menyayangi.","bofrato","ipar"]],
"g|eo|C2|Awalan duon- (Tiri/Setengah)":[["Li estas mia duonfrato.","","Dia adalah saudara tiri saya.","duonfrato","saudara tiri"],["Ŝi estas mia duonfratino.","","Dia adalah saudari tiri saya.","duonfratino","saudari tiri"],["Mia duonfrato loĝas en alia urbo.","","Saudara tiri saya tinggal di kota lain.","duonfrato","Saudara tiri"],["Miaj duonfratoj vivas en Kanado.","","Saudara-saudara tiri saya tinggal di Kanada.","duonfratoj","saudara tiri"],["La duonfrato de mia edzo ĵus edziĝis.","","Saudara tiri suamiku baru saja menikah.","duonfrato","Saudara tiri"],["Mia duonfratino naskiĝis kiam mi estis dek jarojn aĝa.","","Saudari tiri saya lahir ketika saya berusia sepuluh tahun.","duonfratino","Saudari tiri"],["Dimanĉe mi vizitos mian duonfraton kaj lian familion.","","Hari Minggu saya akan mengunjungi saudara tiri saya dan keluarganya.","duonfraton","saudara tiri"],["Ŝi ne konis sian duonfratinon ĝis la morto de la patro.","","Dia tidak mengenal saudari tirinya sampai ayah meninggal.","duonfratinon","saudari tiri"],["Ni estas duonfratoj, sed ni sentas nin kiel veraj fratoj.","","Kami saudara tiri, tetapi merasa seperti saudara kandung.","duonfratoj","saudara tiri"],["Mia duonfratino laboras kiel flegistino en granda hospitalo.","","Saudari tiri saya bekerja sebagai perawat di rumah sakit besar.","duonfratino","Saudari tiri"],["Post la divorco de la gepatroj mi ricevis du duonfratojn.","","Setelah perceraian orang tua, saya mendapat dua saudara tiri.","duonfratojn","saudara tiri"],["Mia duonfrato donis al mi sian malnovan biciklon, kiam li aĉetis novan.","","Saudara tiri saya memberi saya sepeda lamanya ketika dia membeli yang baru.","duonfrato","Saudara tiri"],["Mia duonfratino skribas al mi ĉiumonate, kvankam ni vivas sur malsamaj kontinentoj.","","Saudari tiri saya menulis surat setiap bulan, meskipun kami tinggal di benua berbeda.","duonfratino","Saudari tiri"],["Ŝi kreskis kun sia duonfrato kaj neniam sentis diferencon inter ili.","","Dia tumbuh bersama saudara tirinya dan tak pernah merasakan perbedaan di antara mereka.","duonfrato","saudara tiri"]],
"g|eo|C2|Korespondensi (Surat)":[["Kara amiko!","","Sahabatku yang terkasih,","Kara amiko","Sahabatku yang terkasih"],["Kara Anna!","","Anna yang terkasih,","Kara","terkasih"],["Estimata sinjoro!","","Yang terhormat Tuan,","Estimata sinjoro","Yang terhormat"],["Estimata sinjorino Kovalski!","","Yang terhormat Nyonya Kovalski,","Estimata sinjorino","Yang terhormat"],["Bandung, la 12-an de oktobro 2026.","","Bandung, 12 Oktober 2026","la 12-an de oktobro","12 Oktober"],["Kun korajn salutojn.","","Dengan salam hangat,","Kun korajn salutojn","Dengan salam hangat"],["Kun amikaj salutoj.","","Dengan salam persahabatan,","Kun amikaj salutoj","salam persahabatan"],["Via amiko Petro.","","Sahabatmu, Petro","Via amiko","Sahabatmu"],["Multajn kisojn al vi ĉiuj.","","Banyak ciuman untuk kalian semua,","Multajn kisojn","Banyak ciuman"],["Kun granda danko por via helpo.","","Dengan banyak terima kasih atas bantuanmu,","Kun granda danko","Dengan banyak terima kasih"],["Dankon pro via letero, kiun mi ricevis hieraŭ.","","Terima kasih atas suratmu yang kuterima kemarin.","Dankon pro via letero","Terima kasih atas suratmu"],["Mi skribas al vi por peti informon pri la kurso.","","Saya menulis kepadamu untuk meminta informasi tentang kursus itu.","Mi skribas al vi","Saya menulis kepadamu"],["Bonvolu respondi al mi tuj, kiam vi havos tempon.","","Mohon balas saya segera setelah kamu punya waktu.","Bonvolu respondi","Mohon balas"],["Atendante vian respondon, mi restas kun estimo.","","Sambil menunggu jawabanmu, saya tetap dengan hormat,","Atendante vian respondon","Sambil menunggu jawabanmu"],["Skribu baldaŭ, ĉar ni ĉiuj sopiras vin kaj atendas viajn novaĵojn.","","Segera menulislah, karena kami semua merindukanmu dan menunggu kabarmu.","Skribu baldaŭ","Segera menulislah"]],
"g|eo|C2|Kata Kerja Transitif yang Dijadikan Intransitif (-iĝ-)":[["La laboro finiĝas nun.","","Pekerjaan itu selesai sekarang.","finiĝas",""],["La pordo malfermiĝis mem.","","Pintu itu terbuka sendiri.","malfermiĝis",""],["La glaso rompiĝis sur la planko.","","Gelas itu pecah di lantai.","rompiĝis",""],["La neĝo fandiĝas en la printempo.","","Salju mencair di musim semi.","fandiĝas",""],["La kunveno komenciĝos je la deka.","","Rapat akan dimulai pukul sepuluh.","komenciĝos",""],["Mi ne scias, kie la hundo kaŝiĝis.","","Saya tidak tahu di mana anjing itu bersembunyi.","kaŝiĝis",""],["Ŝi ŝanĝiĝis tre multe en la lastaj jaroj.","","Dia berubah banyak dalam beberapa tahun terakhir.","ŝanĝiĝis",""],["La libro vendiĝas bone en ĉiuj libroservoj.","","Buku itu laris di semua toko buku.","vendiĝas",""],["Mia ĉemizo malsekiĝis, ĉar mi forgesis la pluvombrelon.","","Kemeja saya basah karena saya lupa payung.","malsekiĝis",""],["La vento trankviliĝis antaŭ la mateno.","","Angin mereda sebelum pagi.","trankviliĝis",""],["La ŝipo turniĝis kaj ekveturis al la haveno.","","Kapal itu berputar lalu berlayar menuju pelabuhan.","turniĝis",""],["La instruisto ĉagreniĝis, kiam la studentoj ne alportis siajn hejmtaskojn.","","Guru jengkel ketika para murid tidak membawa PR.","ĉagreniĝis",""],["La temo longe diskutiĝis en la parlamento sen ia decido.","","Topik itu lama dibahas di parlemen tanpa keputusan apa pun.","diskutiĝis",""],["Post la longa pluvo la rivero larĝiĝis kaj inundis la kampojn.","","Setelah hujan panjang sungai itu melebar dan membanjiri ladang.","larĝiĝis",""],["La nova ponto konstruiĝis en nur du jaroj, kvankam oni atendis kvin.","","Jembatan baru itu rampung dibangun hanya dalam dua tahun, padahal orang menduga lima tahun.","konstruiĝis",""]],
"g|eo|C2|Elisi (Penghilangan Huruf)":[["L' espero ne mortas.","","Harapan tidak mati.","L' espero",""],["Dank' al vi mi sukcesis.","","Berkat kamu saya berhasil.","Dank' al","Berkat"],["Dank' al la pluvo la rikolto estis bona.","","Berkat hujan panen menjadi bagus.","Dank' al","Berkat"],["L' amiko venis tre malfrue.","","Sahabat itu datang sangat terlambat.","L' amiko",""],["Mi aŭdis l' ondojn de la maro.","","Saya mendengar ombak laut.","l' ondojn",""],["Ĉu vi aŭdis l' anoncon?","","Apakah kamu mendengar pengumuman itu?","l' anoncon",""],["Mia kor' ĝojas, kiam mi vidas vin.","","Hatiku bersukacita saat melihatmu.","kor'",""],["Ĉiu hom' havas siajn revojn.","","Setiap orang punya mimpinya.","hom'",""],["Dank' al via helpo ni finis frue.","","Berkat bantuanmu kami selesai lebih awal.","Dank' al","Berkat"],["Tra la nokt' ni marŝis sub la steloj.","","Sepanjang malam kami berjalan di bawah bintang.","nokt'",""],["Mi amas l' arton kaj la naturon.","","Saya mencintai seni dan alam.","l' arton",""],["Ŝi vidis l' eniron de la knabo en la ĉambron.","","Dia melihat masuknya anak itu ke kamar.","l' eniron",""],["Dank' al la bona vetero la ekskurso estis agrabla.","","Berkat cuaca bagus tamasya itu menyenangkan.","Dank' al","Berkat"],["En ĉiu vort' de la poemo oni sentas la ĝojon de la aŭtoro.","","Dalam setiap kata puisi itu terasa kegembiraan sang penulis.","vort'",""],["Dank' al la helpo de l' amikoj li trovis novan laboron.","","Berkat bantuan para sahabat dia menemukan pekerjaan baru.","Dank' al","Berkat"]],
"g|eo|C2|Awalan eks- (Mantan)":[["La eksprezidanto loĝas en malgranda vilaĝo.","","Mantan presiden itu tinggal di desa kecil.","eksprezidanto","Mantan presiden"],["Mi renkontis mian eksedzon hieraŭ.","","Saya bertemu mantan suami saya kemarin.","eksedzon","mantan suami"],["Lia eksedzino nun vivas en Aŭstralio.","","Mantan istrinya kini tinggal di Australia.","eksedzino","Mantan istri"],["La eksĉefo ankoraŭ vizitas nian oficejon.","","Mantan atasan masih mengunjungi kantor kami.","eksĉefo","Mantan atasan"],["Li estas eksministro de edukado.","","Dia mantan menteri pendidikan.","eksministro","mantan menteri"],["Nia eksurbestro fondis fundaĵon por infanoj.","","Mantan wali kota kami mendirikan yayasan untuk anak-anak.","eksurbestro","Mantan wali kota"],["Mia eksinstruisto sendis al mi leteron.","","Mantan guru saya mengirimi saya surat.","eksinstruisto","Mantan guru"],["La eksmilitisto rakontis pri la batalo.","","Mantan prajurit itu bercerita tentang pertempuran itu.","eksmilitisto","Mantan prajurit"],["La eksreĝo vivis en ekzilo dum multaj jaroj.","","Mantan raja hidup di pengasingan selama bertahun-tahun.","eksreĝo","Mantan raja"],["Ili estas eksgeedzoj, sed ili restis bonaj amikoj.","","Mereka mantan suami istri, tetapi tetap berteman baik.","eksgeedzoj","mantan suami istri"],["Mia eksedzo ankoraŭ pagas por la edukado de nia filo.","","Mantan suami saya masih membayar pendidikan putra kami.","eksedzo","Mantan suami"],["La eksstudentoj de la universitato renkontiĝis post dudek jaroj.","","Para mantan mahasiswa universitas itu bertemu setelah dua puluh tahun.","eksstudentoj","mantan mahasiswa"],["La eksdirektoro de la banko estis arestita pro ŝtelo.","","Mantan direktur bank itu ditangkap karena pencurian.","eksdirektoro","Mantan direktur"],["La eksprezidanto parolis pri sia ŝtatestra tempo en intervjuo.","","Mantan presiden itu berbicara tentang masa jabatannya dalam wawancara.","eksprezidanto","Mantan presiden"],["Mia eksedzino kaj mi interkonsentis, ke la infanoj vivu kun mi dum la lernojaro.","","Mantan istri saya dan saya sepakat anak-anak tinggal bersama saya selama tahun ajaran.","eksedzino","Mantan istri"]],
"g|eo|C2|Awalan pra- (Leluhur / Zaman Purba)":[["Mia praavo naskiĝis antaŭ cent jaroj.","","Kakek buyut saya lahir seratus tahun lalu.","praavo","Kakek buyut"],["Ŝia praavino ankoraŭ memoras la militon.","","Nenek buyutnya masih ingat perang itu.","praavino","Nenek buyut"],["La prahomo ĉasis mamutojn.","","Manusia purba berburu mamut.","prahomo","purba"],["Mi ŝatas legi pri la prahistorio.","","Saya suka membaca tentang prasejarah.","prahistorio","prasejarah"],["Niaj prapatroj vivis en la montaro.","","Leluhur kami tinggal di pegunungan.","prapatroj","Leluhur"],["Ŝi havas jam kvar pranepojn.","","Dia sudah punya empat cicit.","pranepojn","cicit"],["En la pratempo ĉi tie estis nur arbaro.","","Pada zaman purba di sini hanya ada hutan.","pratempo","purba"],["Tiu praarbaro estas protektata de la ŝtato.","","Hutan purba itu dilindungi negara.","praarbaro","purba"],["La muzeo montras ilojn de la prahomoj.","","Museum itu memamerkan alat-alat manusia purba.","prahomoj","purba"],["Mi trovis malnovan foton de mia praavo kaj praavino.","","Saya menemukan foto lama kakek buyut dan nenek buyut saya.","praavo","kakek buyut"],["La arkeologoj malkovris tombon el la prahistoria epoko.","","Para arkeolog menemukan makam dari zaman prasejarah.","prahistoria","prasejarah"],["Tiu pratempa rito ankoraŭ vivas en kelkaj vilaĝoj.","","Ritual purba itu masih hidup di beberapa desa.","pratempa","purba"],["Mia praavo kaj mia avo ambaŭ estis ĉevalistoj en la sama vilaĝo.","","Kakek buyut dan kakek saya sama-sama penunggang kuda di desa yang sama.","praavo","Kakek buyut"],["La lingvistoj rekonstruis la pralingvon de la ĝermanaj lingvoj.","","Para ahli bahasa merekonstruksi bahasa leluhur rumpun Jermanik.","pralingvon","leluhur"],["Ŝi parolis pri la prapatro, kiu fondis la familian firmaon antaŭ cent jaroj.","","Dia berbicara tentang leluhur yang mendirikan perusahaan keluarga seratus tahun lalu.","prapatro","leluhur"]],
"g|eo|C2|Akhiran -ĉj- dan -nj- (Nama Kesayangan)":[["Paĉjo ankoraŭ ne revenis hejmen.","","Papa belum pulang ke rumah.","Paĉjo","Papa"],["Panjo kaj paĉjo iris al la merkato.","","Mama dan papa pergi ke pasar.","paĉjo","papa"],["Mia paĉjo laboras en banko.","","Papa saya bekerja di bank.","paĉjo","Papa"],["Onĉjo venis kun multaj donacoj.","","Paman datang dengan membawa banyak hadiah.","Onĉjo","Paman"],["Joĉjo estas mia plej bona amiko.","","Joe adalah sahabat terbaik saya.","Joĉjo","Joe"],["Ĉu Peĉjo jam eliris?","","Apakah Pete sudah keluar?","Peĉjo","Pete"],["La infanoj kuris renkonte al paĉjo.","","Anak-anak berlari menyongsong papa.","paĉjo","papa"],["Miĉjo ŝatas ludi futbalon kun la najbaroj.","","Mike suka bermain sepak bola dengan para tetangga.","Miĉjo","Mike"],["Joĉjo havas hundon nomatan Rex.","","Joe punya anjing bernama Rex.","Joĉjo","Joe"],["Dimanĉe ni vizitos onĉjon en la vilaĝo.","","Hari Minggu kami akan mengunjungi paman di desa.","onĉjon","paman"],["Paĉjo diris, ke ni ne iru al la rivero sen li.","","Papa berkata kita jangan pergi ke sungai tanpa dia.","Paĉjo","Papa"],["Peĉjo translokiĝis al Kanado antaŭ du jaroj, sed ankoraŭ skribas al ni.","","Pete pindah ke Kanada dua tahun lalu, tetapi masih menulis kepada kami.","Peĉjo","Pete"],["Per sia sorĉa rideto la malgranda Miĉjo ĉiam ricevas ĉion, kion li volas.","","Dengan senyum memikatnya, Mike kecil selalu mendapatkan semua yang dia mau.","Miĉjo","Mike"],["Mia onĉjo estas ĵurnalisto, kaj li rakontas multajn interesajn aferojn pri siaj vojaĝoj.","","Paman saya wartawan, dan dia menceritakan banyak hal menarik tentang perjalanannya.","onĉjo","Paman"],["Kiam mi estis malgranda, paĉjo ĉiun vesperon rakontis al mi fabelon antaŭ ol mi ekdormis.","","Ketika saya kecil, papa tiap malam menceritakan dongeng kepada saya sebelum saya tertidur.","paĉjo","papa"]],
"g|eo|C2|Akhiran -nj- (Nama Kesayangan Perempuan)":[["Panjo kuiras en la kuirejo.","","Mama memasak di dapur.","Panjo","Mama"],["Ĉu panjo jam venis?","","Apakah mama sudah datang?","panjo","mama"],["Mia panjo ŝatas legi fabelojn.","","Mama saya suka membaca dongeng.","panjo","Mama"],["Onjo Marta venos kun la infanoj.","","Tante Marta akan datang bersama anak-anak.","Onjo","Tante"],["La infanoj kuris al panjo.","","Anak-anak berlari kepada mama.","panjo","mama"],["Hodiaŭ mi helpis panjon en la ĝardeno.","","Hari ini saya membantu mama di kebun.","panjon","mama"],["Mi vizitas mian onjon ĉiun dimanĉon.","","Saya mengunjungi tante saya setiap hari Minggu.","onjon","tante"],["Panjo diris, ke ni lavu la manojn antaŭ ol manĝi.","","Mama berkata agar kita mencuci tangan sebelum makan.","Panjo","Mama"],["Mia onjo loĝas en la urbo kaj havas belan ĝardenon.","","Tante saya tinggal di kota dan punya kebun yang indah.","onjo","Tante"],["Kiam mi estis malsana, panjo restis apud mia lito la tutan nokton.","","Ketika saya sakit, mama tetap di samping tempat tidurku semalaman.","panjo","mama"],["Nia onjo ĉiam alportas al ni dolĉaĵojn el la fremdaj landoj, kiujn ŝi vizitas.","","Tante kami selalu membawakan kami manisan dari negeri asing yang dia kunjungi.","onjo","Tante"],["Post la lernejo mi ĉiam rakontas al panjo, kion mi faris dum la tago.","","Sepulang sekolah saya selalu menceritakan kepada mama apa yang saya lakukan seharian.","panjo","mama"]],
"g|eo|C2|Satuan Berat dan Ukuran (Sistem Metrik)":[["La pano pezas kvincent gramojn.","","Roti itu beratnya lima ratus gram.","gramojn","gram"],["Mi aĉetis unu kilogramon da rizo.","","Saya membeli satu kilogram beras.","kilogramon","kilogram"],["Aldonu cent gramojn da sukero.","","Tambahkan seratus gram gula.","gramojn","gram"],["La bebo pezis tri kilogramojn.","","Bayi itu beratnya tiga kilogram.","kilogramojn","kilogram"],["Mia valizo pezas dudek kilogramojn.","","Koper saya beratnya dua puluh kilogram.","kilogramojn","kilogram"],["La recepto postulas ducent gramojn da faruno.","","Resep itu membutuhkan dua ratus gram tepung.","gramojn","gram"],["Mi aĉetis duonan kilogramon da fromaĝo.","","Saya membeli setengah kilogram keju.","kilogramon","kilogram"],["Ĉi tiu pomo pezas proksimume ducent gramojn.","","Apel ini beratnya sekitar dua ratus gram.","gramojn","gram"],["Unu kilogramo da pomoj kostas du eŭrojn.","","Satu kilogram apel harganya dua euro.","kilogramo","kilogram"],["Ĉiu pakaĵo devas pezi malpli ol dek kilogramojn.","","Setiap paket harus beratnya kurang dari sepuluh kilogram.","kilogramojn","kilogram"],["Mi perdis kvin kilogramojn dum la lastaj tri monatoj.","","Saya turun lima kilogram dalam tiga bulan terakhir.","kilogramojn","kilogram"],["Por tiu kuko vi bezonas dek gramojn da vanilo kaj iom da butero.","","Untuk kue itu kamu butuh sepuluh gram vanili dan sedikit mentega.","gramojn","gram"],["La poŝtisto diris, ke la pakaĵo pezas dudek kvin gramojn tro multe.","","Petugas pos berkata paketnya kelebihan berat dua puluh lima gram.","gramojn","gram"],["La krudmaterialo kostas ĉirkaŭ ses eŭrojn por ĉiu kilogramo.","","Bahan mentahnya harganya sekitar enam euro per kilogram.","kilogramo","kilogram"],["Ŝi laboras en la laboratorio kaj mezuras la pezon de ĉiu specimeno ĝis la plej proksima gramo.","","Dia bekerja di laboratorium dan mengukur berat setiap spesimen hingga gram terdekat.","gramo","gram"]],
"g|eo|C2|Satuan Ukuran (metro, litro)":[["La ĉambro estas kvin metrojn longa.","","Ruangan itu panjangnya lima meter.","metrojn","meter"],["Mi trinkis du litrojn da akvo.","","Saya minum dua liter air.","litrojn","liter"],["La tanko tenas kvindek litrojn.","","Tangki itu memuat lima puluh liter.","litrojn","liter"],["La nova parko okupas tri hektarojn.","","Taman baru itu menempati tiga hektare.","hektarojn","hektare"],["La vilaĝo situas dek kilometrojn de la urbo.","","Desa itu terletak sepuluh kilometer dari kota.","kilometrojn","kilometer"],["La monto estas pli ol mil metrojn alta.","","Gunung itu tingginya lebih dari seribu meter.","metrojn","meter"],["Ni veturis cent kilometrojn en unu horo.","","Kami berkendara seratus kilometer dalam satu jam.","kilometrojn","kilometer"],["Mia aŭto konsumas ses litrojn por cent kilometroj.","","Mobil saya menghabiskan enam liter per seratus kilometer.","litrojn","liter"],["La domo havas ĝardenon de duono de hektaro.","","Rumah itu punya kebun seluas setengah hektare.","hektaro","hektare"],["La maratono longas kvardek du kilometrojn.","","Maraton itu panjangnya empat puluh dua kilometer.","kilometrojn","kilometer"],["La rivero estas ĉirkaŭ cent metrojn larĝa en tiu loko.","","Sungai itu lebarnya sekitar seratus meter di tempat itu.","metrojn","meter"],["La naĝejo estas kvindek metrojn longa kaj dudek metrojn larĝa.","","Kolam renang itu panjangnya lima puluh meter dan lebarnya dua puluh meter.","kvindek metrojn","meter"],["Ĉiu familio ricevas po cent litrojn da akvo ĉiutage.","","Setiap keluarga menerima seratus liter air setiap hari.","litrojn","liter"],["La bieno de mia avo ampleksas kvindek hektarojn da kampoj kaj arbaroj.","","Peternakan kakek saya mencakup lima puluh hektare ladang dan hutan.","hektarojn","hektare"],["Ĝis la proksima benzinejo estas ankoraŭ naŭdek kilometrojn, kaj la benzino preskaŭ elĉerpiĝis.","","Sampai pompa bensin berikutnya masih sembilan puluh kilometer, dan bensinnya hampir habis.","kilometrojn","kilometer"]],
"g|eo|C2|Sistem Mata Uang Internasional (speso)":[["Mi sendas spesmilon kaj duonon.","","Saya mengirim satu setengah spesmilo.","spesmilon","spesmilo"],["Tiu poŝtmarko kostas tri spesojn.","","Prangko itu harganya tiga speso.","spesojn","speso"],["Ĉi tiu libro kostas spesdekon.","","Buku ini harganya satu spesdeko.","spesdekon","spesdeko"],["Por la abono ŝi pagis spescenton.","","Untuk langganan itu dia membayar satu spescento.","spescenton","spescento"],["Unu spesmilo egalas mil spesojn.","","Satu spesmilo sama dengan seribu speso.","spesmilo","spesmilo"],["Mi ricevis kvin spesdekojn kiel premion.","","Saya menerima lima spesdeko sebagai hadiah.","spesdekojn","spesdeko"],["Ŝi pagis du spescentojn por la bileto.","","Dia membayar dua spescento untuk karcisnya.","spescentojn","spescento"],["Spescento sufiĉas por aĉeti ĉi tiun libron.","","Satu spescento cukup untuk membeli buku ini.","Spescento","spescento"],["La estraro donacis tri spesmilojn por la kongreso.","","Pengurus menyumbang tiga spesmilo untuk kongres.","spesmilojn","spesmilo"],["La kongresa komitato kolektis dek spesmilojn por la nova biblioteko.","","Panitia kongres mengumpulkan sepuluh spesmilo untuk perpustakaan baru.","spesmilojn","spesmilo"],["Dum la kongreso oni ŝanĝis spesmilojn en la monon de la lando.","","Selama kongres orang menukar spesmilo dengan mata uang negara itu.","spesmilojn","spesmilo"]],
"g|eo|C2|Singkatan Umum":[["Sro Smith vizitos nin morgaŭ.","","Tuan Smith akan mengunjungi kami besok.","Sro","Tuan"],["Dro Zamenhof kreis la lingvon.","","Dr. Zamenhof menciptakan bahasa itu.","Dro","Dr."],["Sino Lee estas nia nova instruistino.","","Nyonya Lee adalah guru baru kami.","Sino","Nyonya"],["Ni aĉetis pomojn, pirojn, oranĝojn k.t.p.","","Kami membeli apel, pir, jeruk, dan seterusnya.","k.t.p.","dan seterusnya"],["Mi ŝatas fruktojn, ekz. pomojn kaj bananojn.","","Saya suka buah, misalnya apel dan pisang.","ekz.","misalnya"],["Sro kaj Sino Brown loĝas apud la rivero.","","Tuan dan Nyonya Brown tinggal di dekat sungai.","Sro kaj Sino","Tuan dan Nyonya"],["Dro Kovalski prelegos pri la historio de Esperanto.","","Dr. Kovalski akan memberi kuliah tentang sejarah Esperanto.","Dro","Dr."],["Ni bezonas ilojn, ekz. martelon, segilon kaj tenajlojn.","","Kami butuh alat, misalnya palu, gergaji, dan tang.","ekz.","misalnya"],["Ĉe la merkato oni vendas fruktojn, legomojn, fiŝojn k.t.p.","","Di pasar orang menjual buah, sayur, ikan, dan seterusnya.","k.t.p.","dan seterusnya"],["Dro Petro Kim ricevis la premion pri medicino.","","Dr. Petro Kim menerima penghargaan kedokteran.","Dro","Dr."],["En la valizo troviĝis ĉemizoj, ŝtrumpoj, kolumoj k.t.p.","","Di dalam koper ada kemeja, kaus kaki, kerah, dan seterusnya.","k.t.p.","dan seterusnya"],["Mi esperas, ke vi venos, t.e. ke vi ne forgesos la inviton.","","Saya berharap kamu datang, yaitu kamu tidak melupakan undangan itu.","t.e.","yaitu"],["La ĉefa tago, t.e. la dimanĉo, estas libera.","","Hari utamanya, yaitu hari Minggu, bebas.","t.e.","yaitu"],["La ekzamenoj, t.e. la skribaj kaj parolaj testoj, okazos en junio.","","Ujian, yaitu tes tertulis dan lisan, akan berlangsung bulan Juni.","t.e.","yaitu"],["Multaj eŭropaj landoj, ekz. Francio, Germanio kaj Hispanio, ricevas milionojn da turistoj jare.","","Banyak negara Eropa, misalnya Prancis, Jerman, dan Spanyol, menerima jutaan turis setiap tahun.","ekz.","misalnya"]]
});
